@net.minecraftforge.fml.common.Mod("risencombat")
public final class MapRisenCombatTest {
    private final String[] ids={"scarlet_zombie_archer","scarlet_zombie_archer_female","scarlet_zombie_mage","scarlet_zombie_mage_female","scarlet_zombie_archer","scarlet_zombie_archer_female","scarlet_zombie_mage","scarlet_zombie_mage_female","scarlet_zombie_archer","scarlet_zombie_archer_female","scarlet_zombie_mage","scarlet_zombie_mage_female","scarlet_zombie_archer","scarlet_zombie_archer_female","scarlet_zombie_mage","scarlet_zombie_mage_female","scarlet_zombie_archer","scarlet_zombie_archer_female","scarlet_zombie_mage","scarlet_zombie_mage_female","scarlet_zombie_archer","scarlet_zombie_archer_female","scarlet_zombie_mage","scarlet_zombie_mage_female"};
    private net.minecraft.server.MinecraftServer server;private ServerLevel level;private FakePlayer player;private ZombieroolAPI api;private MapActorEntity actor;private int checks,index,age,warmup;private boolean initialized;private net.minecraft.world.entity.Mob geistTarget;private boolean done,projectileDamage;
    public MapRisenCombatTest(){MinecraftForge.EVENT_BUS.addListener(this::start);MinecraftForge.EVENT_BUS.addListener(this::tick);MinecraftForge.EVENT_BUS.addListener((net.minecraftforge.event.entity.living.LivingDamageEvent e)->{if((e.getEntity()==player||e.getEntity()==geistTarget)&&e.getSource().getDirectEntity() instanceof net.minecraft.world.entity.projectile.Arrow)projectileDamage=true;});}
    private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);checks++;System.out.println("PORTABLE CHECK: "+message);}
    private void start(net.minecraftforge.event.server.ServerStartedEvent e){server=e.getServer();level=server.overworld();for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)level.setChunkForced(x,z,true);}
    @SuppressWarnings("unchecked") private void prepare(){try{
        for(int x=-18;x<=32;x++)for(int z=-12;z<=12;z++)for(int y=78;y<86;y++)level.setBlock(new BlockPos(x,y,z),y==78?me.cryo.zombierool.init.ZombieroolModBlocks.PATH.get().defaultBlockState():y==79?net.minecraft.world.level.block.Blocks.STONE.defaultBlockState():net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),2);
        player=new FakePlayer(level,new GameProfile(UUID.randomUUID(),"RisenArsenalTarget")){@Override public boolean isInvulnerableTo(net.minecraft.world.damagesource.DamageSource source){return false;}};level.addNewPlayer(player);player.setGameMode(GameType.SURVIVAL);var protection=ServerPlayer.class.getDeclaredField("spawnInvulnerableTime");protection.setAccessible(true);protection.setInt(player,0);player.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(1000);player.setHealth(1000);
        var players=net.minecraft.server.players.PlayerList.class.getDeclaredField("players");players.setAccessible(true);((List<ServerPlayer>)players.get(server.getPlayerList())).add(player);var byId=net.minecraft.server.players.PlayerList.class.getDeclaredField("playersByUUID");byId.setAccessible(true);((Map<UUID,ServerPlayer>)byId.get(server.getPlayerList())).put(player.getUUID(),player);
        WeaponSystem.Loader.applyWorldWeapons(level);LuaScriptManager.loadScripts(level);api=new ZombieroolAPI(level);
        long count=WeaponSystem.Loader.LOADED_DEFINITIONS.keySet().stream().filter(id->id.startsWith("stratholme_")).count();check(count==16,"All sixteen additional weapons load exclusively from the map pack");
        for(var row:WeaponSystem.Loader.LOADED_DEFINITIONS.entrySet())if(row.getKey().startsWith("stratholme_")){
            var item=net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(new net.minecraft.resources.ResourceLocation("zombierool",row.getKey()));check(item instanceof WeaponSystem.BaseGunItem,"Registered weapon identity: "+row.getKey());var gun=(WeaponSystem.BaseGunItem)item;var stack=new ItemStack(item);gun.initializeIfNeeded(stack);float before=gun.getWeaponDamage(stack);check(before>0&&WeaponFacade.isWeapon(stack)&&!gun.getDefinition().is_wonder_weapon,"Ordinary weapon balance and weapon slot: "+row.getKey());gun.applyPackAPunch(stack);check(gun.getWeaponDamage(stack)>before&&gun.isPackAPunched(stack),"Pack-a-Punch applies real map-defined upgrades: "+row.getKey());
        }
        server.getWorldData().overworldData().setGameTime(100);player.setPos(.5,80,.5);player.setYRot(-90);player.setXRot(0);
        var dummy=me.cryo.zombierool.init.ZombieroolModEntities.ZOMBIE.get().create(level);dummy.moveTo(4.5,80,.5);dummy.setNoAi(true);dummy.setEmergenceTicks(0);dummy.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(1000);dummy.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.ARMOR).setBaseValue(0);dummy.setHealth(1000);level.addFreshEntity(dummy);
        var musket=(WeaponSystem.BaseGunItem)net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(new net.minecraft.resources.ResourceLocation("zombierool","stratholme_musket"));var gunStack=new ItemStack(musket);musket.initializeIfNeeded(gunStack);player.setItemInHand(InteractionHand.MAIN_HAND,gunStack);float spreadBefore=musket.getDefinition().ballistics.spread;musket.getDefinition().ballistics.spread=0;System.out.println("POWDER DEBUG class="+musket.getClass()+" damage="+musket.getWeaponDamage(gunStack)+" range="+musket.getDefinition().stats.range+" eye="+player.getEyePosition(1)+" look="+player.getLookAngle()+" target="+dummy.getBoundingBox()+" query="+level.getEntities(player,player.getBoundingBox().inflate(8)).size());musket.tryShoot(gunStack,player,0,false);musket.getDefinition().ballistics.spread=spreadBefore;check(dummy.getHealth()<1000&&musket.getAmmo(gunStack)==0,"The powder gun fires actual damaging ballistics and consumes its loaded round; health="+dummy.getHealth()+", ammo="+musket.getAmmo(gunStack)+", state="+gunStack.getTag());dummy.discard();
        var bow=(me.cryo.zombierool.item.MapBowItem)net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(new net.minecraft.resources.ResourceLocation("zombierool","stratholme_shortbow"));var bowStack=new ItemStack(bow);bow.initializeIfNeeded(bowStack);player.setItemInHand(InteractionHand.MAIN_HAND,bowStack);bow.tryShoot(bowStack,player,1,false);check(bow.getAmmo(bowStack)==1,"A shoot packet cannot bypass bow draw timing");bow.use(level,player,InteractionHand.MAIN_HAND);bow.releaseUsing(bowStack,level,player,71997);check(bow.getAmmo(bowStack)==1,"A three-tick bow tap does not waste ammunition");bow.releaseUsing(bowStack,level,player,71976);check(bow.getAmmo(bowStack)==0,"Drawing and releasing the bow creates an ammunition-consuming arrow");player.stopUsingItem();
        var sword=(me.cryo.zombierool.item.ScarletWeaponItem)net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(new net.minecraft.resources.ResourceLocation("zombierool","stratholme_arming_sword"));var blade=new ItemStack(sword);sword.initializeIfNeeded(blade);player.setItemInHand(InteractionHand.MAIN_HAND,blade);var target=me.cryo.zombierool.init.ZombieroolModEntities.ZOMBIE.get().create(level);target.moveTo(2,80,.5);target.setNoAi(true);target.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(1000);target.setHealth(1000);level.addFreshEntity(target);target.setEmergenceTicks(0);float light=0;for(int hit=0;hit<3;hit++){level.getServer().getWorldData().overworldData().setGameTime(500+hit*40);if(hit>0)blade.getOrCreateTag().putLong(WeaponSystem.BaseGunItem.TAG_LAST_FIRE,level.getGameTime()-sword.getFireRate(blade,player));float before=target.getHealth();check(sword.hurtEnemy(blade,target,player),"Sword combo hit "+hit);if(hit==0)light=before-target.getHealth();if(hit==2)check(before-target.getHealth()>light,"Third sword hit is a stronger finisher");}
        level.getServer().getWorldData().overworldData().setGameTime(1000);player.getCooldowns().removeCooldown(sword);float beforeHeavy=target.getHealth();int condition=sword.getDurability(blade);sword.releaseUsing(blade,level,player,71980);check(beforeHeavy-target.getHealth()>light*1.7&&sword.getDurability(blade)==condition-3,"Charged melee strike deals increased damage and costs three durability");target.discard();player.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);if(Boolean.getBoolean("zr.geistOnly"))index=12;next();
    }catch(Throwable t){fail(t);}}
    private int testDistance(){return index<12?8+(index/4)*8:8+((index-12)/4)*8;}
    private void next(){
        if(geistTarget!=null){geistTarget.discard();geistTarget=null;}MapActors.end(level);for(var e:level.getAllEntities())if(e instanceof net.minecraft.world.entity.projectile.Projectile)e.discard();player.removeAllEffects();player.setHealth(1000);player.invulnerableTime=0;player.setPos(testDistance()+.5,80,.5);projectileDamage=false;age=0;
        String uuid=MapActors.get(level).spawn(level,ids[index],new net.minecraft.world.phys.Vec3(.5,80,.5),"");check(!uuid.isEmpty(),"Ranged Risen spawns: "+ids[index]);actor=(MapActorEntity)level.getEntity(UUID.fromString(uuid));var saved=new net.minecraft.nbt.CompoundTag();actor.addAdditionalSaveData(saved);saved.getCompound("MapProfile").putString("callback","");actor.readAdditionalSaveData(saved);check(!actor.profile().getString("callback").isEmpty(),"Saved Risen refreshes its current ranged callback");if(index>=12){player.setPos(30.5,80,-8.5);
            if(index<16){geistTarget=me.cryo.zombierool.init.ZombieroolModEntities.GEIST.get().create(level);geistTarget.moveTo(testDistance()+.5,80,.5);geistTarget.getPersistentData().putBoolean("zr_debug_spawn",true);level.addFreshEntity(geistTarget);}else geistTarget=(net.minecraft.world.entity.Mob)level.getEntity(UUID.fromString(MapActors.get(level).spawn(level,"builtin_geist",new net.minecraft.world.phys.Vec3(testDistance()+.5,80,.5),"")));
            geistTarget.setNoAi(true);((me.cryo.zombierool.entity.AbstractZombieRoolEntity)geistTarget).setEmergenceTicks(0);geistTarget.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(1000);geistTarget.setHealth(1000);player.setPos(30.5,80,-8.5);actor.setTarget(geistTarget);check(MapActorBehavior.enemies(actor,geistTarget),"Ranged Risen recognizes the Geist as hostile");
            var friendly=new net.minecraft.world.entity.projectile.Arrow(level,actor);friendly.getPersistentData().putBoolean("zr_actor_bolt",true);friendly.getPersistentData().putFloat("damage",2);var ally=me.cryo.zombierool.init.ZombieroolModEntities.MAP_ACTOR.get().create(level);ally.configure(MapActors.get(level).profile("scarlet_zombie"),actor.position(),"");var impact=new net.minecraftforge.event.entity.ProjectileImpactEvent(friendly,new net.minecraft.world.phys.EntityHitResult(ally));net.minecraftforge.common.MinecraftForge.EVENT_BUS.post(impact);check(impact.isCanceled()&&!friendly.isRemoved(),"A Risen ally does not consume the faction projectile");
            ally.setHealth(0);impact=new net.minecraftforge.event.entity.ProjectileImpactEvent(friendly,new net.minecraft.world.phys.EntityHitResult(ally));net.minecraftforge.common.MinecraftForge.EVENT_BUS.post(impact);check(impact.isCanceled()&&!friendly.isRemoved(),"A corpse does not consume the faction projectile");
        }else actor.setTarget(player);check(!actor.hasCustomName()&&actor.profile().getBoolean("sourceMotion")&&actor.profile().getString("faction").equals("risen"),"Risen role preserves map motion, faction and hidden nametag: "+ids[index]);
    }
    private void tick(TickEvent.ServerTickEvent e){if(done||e.phase!=TickEvent.Phase.END||server==null)return;if(!initialized){if(++warmup<60)return;initialized=true;prepare();return;}if(actor==null)return;try{
        age++;actor.setPos(.5,80,.5);actor.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);player.setPos(testDistance()+.5,80,.5);player.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);player.fallDistance=0;
        if(geistTarget!=null){geistTarget.setPos(testDistance()+.5,80,.5+(index>=20?Math.sin(age*.12)*1.5:0));geistTarget.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);player.setPos(30.5,80,-8.5);
            if(projectileDamage&&geistTarget.getHealth()<1000){check(true,"Real "+(ids[index].contains("mage")?"mage spell":"archer arrow")+" damages "+(index<16?"round":index>=20?"moving spawner":"spawner")+" Geist: "+ids[index]+" health="+geistTarget.getHealth());actor.discard();actor=null;if(++index==ids.length){done=true;System.out.println("PORTABLE RUNTIME PASS: "+checks+" Risen and arsenal checks");server.halt(false);}else next();}
            else if(age>340)throw new AssertionError("No real projectile damage to Geist from "+ids[index]+" target="+actor.getTarget()+" box="+geistTarget.getBoundingBox()+" health="+geistTarget.getHealth()+" Lua="+LuaScriptManager.console());return;
        }
        if(projectileDamage&&player.getHealth()<1000){
            check(1000-player.getHealth()>=(ids[index].contains("mage")?3:2)-.01,"Authored projectile damage reaches the stationary player at "+(8+(index/4)*8)+" blocks: "+ids[index]+" lost="+(1000-player.getHealth()));for(var entity:level.getAllEntities())if(entity instanceof net.minecraft.world.entity.projectile.Arrow shot&&shot.getOwner()==actor)check(!shot.getPersistentData().hasUUID("factionTarget"),"Player-directed spells never use faction target tracking");check(actor.distanceToSqr(player)>9,"Risen lands a real projectile hit from beyond melee range: "+ids[index]);
            var scourge=me.cryo.zombierool.entity.ZombieEntity.class.cast(level.getEntity(UUID.fromString(MapActors.get(level).spawn(level,"builtin_ghoul",new net.minecraft.world.phys.Vec3(8.5,80,5.5),""))));scourge.setNoAi(true);float before=scourge.getHealth();actor.getPersistentData().remove("lastBolt");
            check(api.shootMapActor(actor.getUUID().toString(),scourge.getUUID().toString(),"arrow",2,2),"The same projectile API accepts a hostile Scourge target: "+ids[index]);
            net.minecraft.world.entity.projectile.Arrow bolt=null;for(var entity:level.getAllEntities())if(entity instanceof net.minecraft.world.entity.projectile.Arrow arrow&&arrow.getOwner()==actor&&arrow.getPersistentData().getBoolean("zr_actor_bolt"))bolt=arrow;
            check(bolt!=null,"Faction projectile exists in the actual world");MapActors.impact(new net.minecraftforge.event.entity.ProjectileImpactEvent(bolt,new net.minecraft.world.phys.EntityHitResult(scourge)));check(scourge.getHealth()<before,"Faction projectile damage reaches the Scourge enemy");
            actor.discard();actor=null;if(++index==ids.length){done=true;System.out.println("PORTABLE RUNTIME PASS: "+checks+" Risen and arsenal checks");server.halt(false);}else next();
        }else if(age>340)throw new AssertionError("No ranged hit from "+ids[index]+"; target="+actor.getTarget()+" distance="+actor.distanceTo(player)+" Lua="+LuaScriptManager.console());
    }catch(Throwable t){fail(t);}}
    private void fail(Throwable t){done=true;t.printStackTrace();System.out.println("PORTABLE RUNTIME FAIL: "+t);if(server!=null)server.halt(false);}
}
